#!/usr/bin/env bash
set -euo pipefail

cd "${HOME}/poema-universal"

echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
echo " ORGANISMO · EMBRIÓN 3D REAL"
echo " BIO-CIBERNÉTICA SAGRADA · NIVEL 2"
echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"

if [[ ! -f package.json ]]; then
  echo "❌ No encuentro package.json en ~/poema-universal"
  exit 1
fi

if [[ -d app/laboratorio/verso-tecno ]]; then
  TARGET="app/laboratorio/verso-tecno"
elif [[ -d src/app/laboratorio/verso-tecno ]]; then
  TARGET="src/app/laboratorio/verso-tecno"
else
  echo "❌ No encuentro la sala /laboratorio/verso-tecno"
  exit 1
fi

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="${TARGET}.before-embryo-3d-${STAMP}"
cp -R "${TARGET}" "${BACKUP}"

echo "✅ Copia de seguridad: ${BACKUP}"

mkdir -p public/models/organismo
mkdir -p "${TARGET}/organismo"

echo "===== INSTALANDO MOTOR 3D ====="
npm install three
npm install -D @types/three

echo "===== RECONSTRUYENDO MODELO GLB ====="
python3 - <<'PYMODEL'
from pathlib import Path
import base64

payload = r""""""
target = Path("public/models/organismo/embrion-organismo.glb")
target.write_bytes(base64.b64decode(payload))
print(f"✅ Modelo instalado: {target}")
print(f"✅ Tamaño: {target.stat().st_size / 1024 / 1024:.2f} MB")
PYMODEL

cat > "${TARGET}/organismo/OrganismoEmbryoScene.tsx" <<'EOF'
"use client";

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import type { Organismo } from "./motor";
import styles from "../verso-tecno.module.css";

type SceneResources = {
  renderer: THREE.WebGLRenderer;
  frame: number;
  resizeObserver: ResizeObserver;
  disposables: Array<THREE.BufferGeometry | THREE.Material | THREE.Texture>;
};

function disposeMaterial(
  material: THREE.Material,
  disposables: SceneResources["disposables"],
) {
  disposables.push(material);

  const possibleTextures = material as THREE.Material & {
    map?: THREE.Texture | null;
    normalMap?: THREE.Texture | null;
    roughnessMap?: THREE.Texture | null;
    metalnessMap?: THREE.Texture | null;
    emissiveMap?: THREE.Texture | null;
    alphaMap?: THREE.Texture | null;
  };

  [
    possibleTextures.map,
    possibleTextures.normalMap,
    possibleTextures.roughnessMap,
    possibleTextures.metalnessMap,
    possibleTextures.emissiveMap,
    possibleTextures.alphaMap,
  ].forEach((texture) => {
    if (texture) disposables.push(texture);
  });
}

export default function OrganismoEmbryoScene({
  organismo,
}: {
  organismo: Organismo;
}) {
  const mountRef = useRef<HTMLDivElement | null>(null);
  const [estado, setEstado] = useState<"cargando" | "activo" | "error">(
    "cargando",
  );

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;

    setEstado("cargando");

    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x050706, 0.13);

    const camera = new THREE.PerspectiveCamera(34, 1, 0.1, 100);
    camera.position.set(0, 0.03, 4.65);

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: "high-performance",
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.65));
    renderer.setSize(mount.clientWidth, mount.clientHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.domElement.className = styles.embryoCanvas;
    mount.appendChild(renderer.domElement);

    const resources: SceneResources = {
      renderer,
      frame: 0,
      resizeObserver: new ResizeObserver(() => undefined),
      disposables: [],
    };

    const root = new THREE.Group();
    root.rotation.x = -0.04;
    scene.add(root);

    const capsuleGroup = new THREE.Group();
    root.add(capsuleGroup);

    const liquidGeometry = new THREE.SphereGeometry(1.34, 64, 64);
    liquidGeometry.scale(0.82, 1.19, 0.78);
    resources.disposables.push(liquidGeometry);

    const liquidMaterial = new THREE.MeshPhysicalMaterial({
      color: 0x7e8e18,
      transparent: true,
      opacity: 0.105,
      roughness: 0.08,
      metalness: 0,
      transmission: 0.62,
      thickness: 0.62,
      ior: 1.31,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    resources.disposables.push(liquidMaterial);

    const liquid = new THREE.Mesh(liquidGeometry, liquidMaterial);
    liquid.renderOrder = 1;
    capsuleGroup.add(liquid);

    const shellGeometry = new THREE.SphereGeometry(1.42, 72, 72);
    shellGeometry.scale(0.84, 1.22, 0.8);
    resources.disposables.push(shellGeometry);

    const shellMaterial = new THREE.MeshPhysicalMaterial({
      color: 0xb5c66d,
      transparent: true,
      opacity: 0.14,
      transmission: 0.92,
      roughness: 0.03,
      metalness: 0.02,
      thickness: 0.18,
      ior: 1.47,
      clearcoat: 1,
      clearcoatRoughness: 0.08,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    resources.disposables.push(shellMaterial);

    const shell = new THREE.Mesh(shellGeometry, shellMaterial);
    shell.renderOrder = 4;
    capsuleGroup.add(shell);

    const innerMembraneGeometry = new THREE.SphereGeometry(1.23, 48, 48);
    innerMembraneGeometry.scale(0.78, 1.12, 0.73);
    resources.disposables.push(innerMembraneGeometry);

    const innerMembraneMaterial = new THREE.MeshBasicMaterial({
      color: 0xd9ff59,
      transparent: true,
      opacity: 0.035,
      wireframe: true,
      depthWrite: false,
    });
    resources.disposables.push(innerMembraneMaterial);

    const innerMembrane = new THREE.Mesh(
      innerMembraneGeometry,
      innerMembraneMaterial,
    );
    capsuleGroup.add(innerMembrane);

    const ringGroup = new THREE.Group();
    root.add(ringGroup);

    [-1.46, -1.2, 1.2, 1.46].forEach((y, index) => {
      const radius = index === 0 || index === 3 ? 1.08 : 1.18;
      const ringGeometry = new THREE.TorusGeometry(
        radius,
        index === 0 || index === 3 ? 0.055 : 0.025,
        18,
        120,
      );
      resources.disposables.push(ringGeometry);

      const ringMaterial = new THREE.MeshStandardMaterial({
        color: index % 2 === 0 ? 0x1d211d : 0x313a20,
        metalness: 0.92,
        roughness: 0.24,
        emissive: new THREE.Color(index % 2 === 0 ? 0x302400 : 0x172400),
        emissiveIntensity: 0.35,
      });
      resources.disposables.push(ringMaterial);

      const ring = new THREE.Mesh(ringGeometry, ringMaterial);
      ring.rotation.x = Math.PI / 2;
      ring.position.y = y;
      ring.scale.x = 0.84;
      ring.scale.z = 0.8;
      ring.castShadow = true;
      ringGroup.add(ring);
    });

    const haloGroup = new THREE.Group();
    root.add(haloGroup);

    [1.68, 1.92, 2.2].forEach((radius, index) => {
      const haloGeometry = new THREE.TorusGeometry(
        radius,
        index === 1 ? 0.012 : 0.007,
        10,
        160,
      );
      resources.disposables.push(haloGeometry);

      const haloMaterial = new THREE.MeshBasicMaterial({
        color: index === 1 ? 0xef7145 : 0xd9ff59,
        transparent: true,
        opacity: 0.16 - index * 0.025,
        depthWrite: false,
      });
      resources.disposables.push(haloMaterial);

      const halo = new THREE.Mesh(haloGeometry, haloMaterial);
      halo.rotation.x = Math.PI / 2 + (index - 1) * 0.16;
      halo.rotation.y = (index - 1) * 0.2;
      haloGroup.add(halo);
    });

    const particleCount = Math.min(
      950,
      340 + organismo.complejidad * 7 + organismo.memoriaVital * 2,
    );
    const positions = new Float32Array(particleCount * 3);
    const sizes = new Float32Array(particleCount);

    for (let index = 0; index < particleCount; index += 1) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const radius = 0.32 + Math.pow(Math.random(), 0.72) * 1.5;

      positions[index * 3] =
        Math.sin(phi) * Math.cos(theta) * radius * 0.78;
      positions[index * 3 + 1] =
        Math.cos(phi) * radius * 1.12;
      positions[index * 3 + 2] =
        Math.sin(phi) * Math.sin(theta) * radius * 0.74;
      sizes[index] = 0.5 + Math.random();
    }

    const particleGeometry = new THREE.BufferGeometry();
    particleGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(positions, 3),
    );
    particleGeometry.setAttribute(
      "size",
      new THREE.BufferAttribute(sizes, 1),
    );
    resources.disposables.push(particleGeometry);

    const particleMaterial = new THREE.PointsMaterial({
      color: 0xd9ff59,
      size: 0.012,
      transparent: true,
      opacity: 0.53,
      sizeAttenuation: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    resources.disposables.push(particleMaterial);

    const particles = new THREE.Points(
      particleGeometry,
      particleMaterial,
    );
    root.add(particles);

    const filamentGroup = new THREE.Group();
    root.add(filamentGroup);

    const filamentCount = Math.min(
      24,
      8 + Math.round(organismo.complejidad / 7),
    );

    for (let index = 0; index < filamentCount; index += 1) {
      const angle = (Math.PI * 2 * index) / filamentCount;
      const reach = 1.34 + Math.random() * 0.48;

      const curve = new THREE.CatmullRomCurve3([
        new THREE.Vector3(
          Math.cos(angle) * 0.34,
          Math.sin(angle * 1.8) * 0.26,
          Math.sin(angle) * 0.23,
        ),
        new THREE.Vector3(
          Math.cos(angle + 0.32) * 0.73,
          Math.sin(angle * 1.3) * 0.72,
          Math.sin(angle + 0.32) * 0.49,
        ),
        new THREE.Vector3(
          Math.cos(angle) * reach * 0.78,
          Math.sin(angle * 0.8) * reach,
          Math.sin(angle) * reach * 0.65,
        ),
      ]);

      const filamentGeometry = new THREE.TubeGeometry(
        curve,
        36,
        0.004 + (index % 4) * 0.0013,
        6,
        false,
      );
      resources.disposables.push(filamentGeometry);

      const filamentMaterial = new THREE.MeshBasicMaterial({
        color: index % 5 === 0 ? 0xef7145 : 0xd9ff59,
        transparent: true,
        opacity: 0.12 + (index % 3) * 0.04,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      });
      resources.disposables.push(filamentMaterial);

      filamentGroup.add(
        new THREE.Mesh(filamentGeometry, filamentMaterial),
      );
    }

    const ambient = new THREE.AmbientLight(0x506020, 0.72);
    scene.add(ambient);

    const keyLight = new THREE.PointLight(
      0xffc56a,
      5.2 + organismo.energia * 0.028,
      9,
      1.7,
    );
    keyLight.position.set(1.45, 1.0, 2.35);
    keyLight.castShadow = true;
    scene.add(keyLight);

    const sacredLight = new THREE.PointLight(
      0xd9ff59,
      3.3 + organismo.memoriaVital * 0.02,
      8,
      1.8,
    );
    sacredLight.position.set(-1.2, -0.25, 1.45);
    scene.add(sacredLight);

    const rimLight = new THREE.DirectionalLight(0x89a9ff, 1.18);
    rimLight.position.set(-3.2, 2.2, -2.8);
    scene.add(rimLight);

    const lowerLight = new THREE.PointLight(0xef7145, 1.4, 6);
    lowerLight.position.set(0.2, -2.1, 0.8);
    scene.add(lowerLight);

    let embryo: THREE.Group | null = null;
    const loader = new GLTFLoader();

    loader.load(
      "/models/organismo/embrion-organismo.glb",
      (gltf) => {
        embryo = gltf.scene;

        const box = new THREE.Box3().setFromObject(embryo);
        const center = box.getCenter(new THREE.Vector3());
        const size = box.getSize(new THREE.Vector3());
        const largest = Math.max(size.x, size.y, size.z);
        const scale = 1.76 / Math.max(0.001, largest);

        embryo.position.sub(center);
        embryo.scale.setScalar(scale);
        embryo.rotation.set(-0.04, -0.28, 0.045);
        embryo.position.y = -0.02;
        embryo.renderOrder = 2;

        embryo.traverse((object) => {
          if (!(object instanceof THREE.Mesh)) return;

          object.castShadow = true;
          object.receiveShadow = true;

          const originals = Array.isArray(object.material)
            ? object.material
            : [object.material];

          const materials = originals.map((original) => {
            const cloned = original.clone();

            if (cloned instanceof THREE.MeshStandardMaterial) {
              cloned.roughness = 0.48;
              cloned.metalness = 0.02;
              cloned.emissive = new THREE.Color(0x2e1d00);
              cloned.emissiveIntensity =
                0.18 + organismo.energia * 0.0025;
              cloned.envMapIntensity = 0.72;
              cloned.side = THREE.DoubleSide;
              cloned.needsUpdate = true;
            }

            disposeMaterial(cloned, resources.disposables);
            return cloned;
          });

          object.material = Array.isArray(object.material)
            ? materials
            : materials[0];
        });

        root.add(embryo);
        setEstado("activo");
      },
      undefined,
      (error) => {
        console.error("No se pudo cargar el embrión 3D:", error);
        setEstado("error");
      },
    );

    const pointer = new THREE.Vector2();
    const targetRotation = new THREE.Vector2();

    function handlePointerMove(event: PointerEvent) {
      const rect = mount.getBoundingClientRect();
      pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
      targetRotation.x = pointer.y * 0.055;
      targetRotation.y = pointer.x * 0.12;
    }

    mount.addEventListener("pointermove", handlePointerMove);

    resources.resizeObserver = new ResizeObserver(() => {
      const width = Math.max(1, mount.clientWidth);
      const height = Math.max(1, mount.clientHeight);

      camera.aspect = width / height;
      camera.updateProjectionMatrix();
      renderer.setSize(width, height);
    });
    resources.resizeObserver.observe(mount);

    const clock = new THREE.Clock();
    const bpm = Math.max(42, organismo.bpmBase);
    const beatFrequency = bpm / 60;
    const stageFactor =
      organismo.etapa === "embrion"
        ? 0.55
        : organismo.etapa === "germinacion"
          ? 0.7
          : organismo.etapa === "latencia"
            ? 0.35
            : 1;

    function animate() {
      const elapsed = clock.getElapsedTime();
      const pulse =
        Math.sin(elapsed * Math.PI * 2 * beatFrequency) * 0.5 + 0.5;
      const breath = Math.sin(elapsed * 1.12) * 0.5 + 0.5;

      root.rotation.x +=
        (targetRotation.x - root.rotation.x) * 0.025;
      root.rotation.y +=
        (targetRotation.y + Math.sin(elapsed * 0.09) * 0.055 -
          root.rotation.y) *
        0.022;

      capsuleGroup.position.y = Math.sin(elapsed * 0.52) * 0.026;
      capsuleGroup.rotation.y = Math.sin(elapsed * 0.16) * 0.025;

      liquidMaterial.opacity =
        0.075 +
        organismo.memoriaVital * 0.0004 +
        breath * 0.026;

      shellMaterial.opacity =
        0.1 +
        organismo.estabilidad * 0.00045 +
        pulse * 0.025 * stageFactor;

      innerMembraneMaterial.opacity =
        0.018 +
        organismo.complejidad * 0.00025 +
        pulse * 0.018;

      shell.scale.setScalar(1 + pulse * 0.006 * stageFactor);
      innerMembrane.rotation.y = elapsed * 0.055;
      innerMembrane.rotation.x = elapsed * -0.032;

      haloGroup.rotation.y = elapsed * 0.052;
      haloGroup.rotation.z = Math.sin(elapsed * 0.14) * 0.09;
      ringGroup.rotation.y = Math.sin(elapsed * 0.13) * 0.025;

      particles.rotation.y = elapsed * 0.025;
      particles.rotation.z = elapsed * -0.012;
      particleMaterial.opacity =
        0.31 +
        organismo.complejidad * 0.002 +
        pulse * 0.13;

      filamentGroup.rotation.y = elapsed * -0.018;
      filamentGroup.scale.setScalar(
        0.99 + breath * 0.018 * stageFactor,
      );

      keyLight.intensity =
        3.7 +
        organismo.energia * 0.024 +
        pulse * 1.35 * stageFactor;
      sacredLight.intensity =
        2.25 +
        organismo.memoriaVital * 0.019 +
        breath * 0.72;

      if (embryo) {
        const embryoBreath =
          1 +
          Math.sin(elapsed * 1.2) *
            (0.004 + organismo.energia * 0.000025) *
            stageFactor;

        embryo.scale.multiplyScalar(
          embryoBreath /
            (embryo.userData.lastBreathScale ?? 1),
        );
        embryo.userData.lastBreathScale = embryoBreath;
        embryo.position.y =
          -0.02 + Math.sin(elapsed * 0.62) * 0.028 * stageFactor;
        embryo.rotation.y =
          -0.28 + Math.sin(elapsed * 0.21) * 0.035;
      }

      renderer.render(scene, camera);
      resources.frame = window.requestAnimationFrame(animate);
    }

    animate();

    return () => {
      window.cancelAnimationFrame(resources.frame);
      resources.resizeObserver.disconnect();
      mount.removeEventListener("pointermove", handlePointerMove);

      resources.disposables.forEach((resource) => {
        resource.dispose();
      });

      renderer.dispose();
      renderer.forceContextLoss();

      if (renderer.domElement.parentElement === mount) {
        mount.removeChild(renderer.domElement);
      }
    };
  }, [
    organismo.codigo,
    organismo.edad,
    organismo.etapa,
    organismo.energia,
    organismo.estabilidad,
    organismo.memoriaVital,
    organismo.complejidad,
    organismo.bpmBase,
  ]);

  return (
    <div className={styles.embryoScene} ref={mountRef}>
      <div className={styles.embryoVignette} aria-hidden="true" />
      <div className={styles.embryoScan} aria-hidden="true" />

      <div className={styles.embryoTelemetry}>
        <span>{organismo.codigo}</span>
        <span>{organismo.etapa.toUpperCase()}</span>
      </div>

      <div className={styles.embryoStatus}>
        {estado === "cargando" ? "FORMANDO CUERPO 3D…" : null}
        {estado === "error" ? "EL MODELO NO PUDO MANIFESTARSE" : null}
      </div>

      <div className={styles.embryoWord}>
        <small>NÚCLEO</small>
        <strong>{organismo.reliquia}</strong>
        <span>DÍA {String(organismo.edad).padStart(2, "0")}</span>
      </div>
    </div>
  );
}
EOF

python3 - "${TARGET}/VersoTecno.tsx" <<'PYTSX'
from pathlib import Path
import sys

path = Path(sys.argv[1])
text = path.read_text(encoding="utf-8")

old_import = 'import OrganismoVisual from "./organismo/OrganismoVisual";'
new_import = 'import OrganismoEmbryoScene from "./organismo/OrganismoEmbryoScene";'

if old_import in text:
    text = text.replace(old_import, new_import, 1)
elif new_import not in text:
    raise SystemExit("❌ No encuentro la importación de OrganismoVisual.")

old_component = "<OrganismoVisual organismo={organismo} />"
new_component = "<OrganismoEmbryoScene organismo={organismo} />"

if old_component in text:
    text = text.replace(old_component, new_component, 1)
elif new_component not in text:
    raise SystemExit("❌ No encuentro el componente OrganismoVisual.")

path.write_text(text, encoding="utf-8")
print("✅ Cámara vital conectada al embrión 3D.")
PYTSX

cat >> "${TARGET}/verso-tecno.module.css" <<'EOF'

/* =========================================================
   ORGANISMO · EMBRIÓN 3D REAL · BIO-CIBERNÉTICA SAGRADA
   ========================================================= */

.embryoScene {
  position: relative;
  min-height: 500px;
  overflow: hidden;
  margin-top: 15px;
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 50% 48%, rgba(217, 255, 89, 0.105), transparent 36%),
    radial-gradient(circle at 50% 57%, rgba(239, 113, 69, 0.09), transparent 51%),
    linear-gradient(180deg, #050706 0%, #070907 50%, #030504 100%);
  isolation: isolate;
}

.embryoScene::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    linear-gradient(rgba(217, 255, 89, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(217, 255, 89, 0.026) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: radial-gradient(circle at center, transparent 17%, black 85%);
}

.embryoCanvas {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  cursor: crosshair;
  touch-action: none;
}

.embryoVignette {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  box-shadow:
    inset 0 0 90px rgba(0, 0, 0, 0.82),
    inset 0 -80px 120px rgba(0, 0, 0, 0.54);
}

.embryoScan {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  opacity: 0.18;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent 3px,
    rgba(217, 255, 89, 0.035) 4px
  );
  animation: embryoScan 9s linear infinite;
}

.embryoTelemetry {
  position: absolute;
  right: 12px;
  bottom: 11px;
  left: 12px;
  z-index: 6;
  display: flex;
  justify-content: space-between;
  color: rgba(239, 237, 226, 0.43);
  font-size: 7px;
  letter-spacing: 0.17em;
  pointer-events: none;
}

.embryoStatus {
  position: absolute;
  top: 13px;
  left: 13px;
  z-index: 7;
  color: var(--acid);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.17em;
  pointer-events: none;
}

.embryoWord {
  position: absolute;
  left: 50%;
  bottom: 28px;
  z-index: 6;
  display: flex;
  align-items: center;
  flex-direction: column;
  max-width: 72%;
  transform: translateX(-50%);
  text-align: center;
  pointer-events: none;
  text-shadow: 0 2px 18px #000;
}

.embryoWord small {
  color: rgba(239, 237, 226, 0.5);
  font-size: 6px;
  font-weight: 800;
  letter-spacing: 0.2em;
}

.embryoWord strong {
  max-width: 100%;
  overflow: hidden;
  margin-top: 4px;
  color: var(--ink);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 16px;
  font-weight: 400;
  font-style: italic;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.embryoWord span {
  margin-top: 4px;
  color: var(--acid);
  font-size: 6px;
  letter-spacing: 0.18em;
}

@keyframes embryoScan {
  from {
    transform: translateY(-10px);
  }

  to {
    transform: translateY(10px);
  }
}

@media (max-width: 620px) {
  .embryoScene {
    min-height: 420px;
  }

  .embryoWord {
    bottom: 23px;
  }
}
EOF

rm -rf .next

echo ""
echo "===== COMPROBANDO TYPESCRIPT ====="
